import React, { useState, useEffect } from 'react';
import './Home.css';

function LoginSignup() {
  const [currState, setCurrState] = useState("Login");
  const [isLoggedIn, setIsLoggedIn] = useState(localStorage.getItem('isLoggedIn') === 'true');
  const [showLoginPopup, setShowLoginPopup] = useState(false);
  const [showForgotPasswordPopup, setShowForgotPasswordPopup] = useState(false);
  const [name, setName] = useState('');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [forgotEmail, setForgotEmail] = useState('');
  const [newForgotPassword, setNewForgotPassword] = useState('');
  const [agreeTerms, setAgreeTerms] = useState(false);
  const [showProfileOptions, setShowProfileOptions] = useState(false);

  const [onLoginSuccessCallback, setOnLoginSuccessCallback] = useState(null);

  const updateAuthUI = () => {
    if (isLoggedIn) {
      document.getElementById('sign-in-btn').style.display = "none";
      document.getElementById('profile-icon').style.display = "inline-block";
    } else {
      document.getElementById('sign-in-btn').style.display = "inline-block";
      document.getElementById('profile-icon').style.display = "none";
      setShowProfileOptions(false); // Hide options on logout
    }
  };

  const togglePopup = (popupType) => {
    if (popupType === 'login') {
      setShowLoginPopup(true);
      setShowForgotPasswordPopup(false);
      setCurrState("Login");
    } else if (popupType === 'forgot') {
      setShowForgotPasswordPopup(true);
      setShowLoginPopup(false);
    } else {
      setShowLoginPopup(false);
      setShowForgotPasswordPopup(false);
    }
    document.body.classList.toggle("no-scroll", showLoginPopup || showForgotPasswordPopup);
  };

  const updatePopupState = (newState) => {
    setCurrState(newState);
    setName('');
    setEmail('');
    setPassword('');
    setAgreeTerms(false);
  };

  const toggleState = () => {
    updatePopupState(currState === "Login" ? "Sign Up" : "Login");
  };

  const handleFormSubmission = async (url, data, successMessage, errorHandler) => {
    try {
      const response = await fetch(url, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(data),
      });
      const result = await response.json();
      if (response.ok) {
        alert(successMessage);
        return result;
      } else {
        console.error(`Error:`, result.message);
        errorHandler(result);
        return null;
      }
    } catch (error) {
      console.error("Submission Error:", error);
      alert("Something went wrong, please try again.");
      return null;
    }
  };

  const handleForgotPasswordSubmit = async (event) => {
    event.preventDefault();
    if (!forgotEmail) { alert("Please enter your email address."); return; }
    if (!newForgotPassword) { alert("Please enter your new password."); return; }
    if (newForgotPassword.length < 6) { alert("New password must be at least 6 characters long."); return; }

    const data = await handleFormSubmission(
      "http://localhost:5000/user/change-password",
      { email: forgotEmail, newPassword: newForgotPassword },
      "Password reset successful! You can now log in.",
      (errorData) => {
        if (errorData && errorData.message === 'User not found') {
          alert("No user found with that email address.");
        } else {
          alert(`Password reset failed: ${errorData.message || "Something went wrong."}`);
        }
      }
    );
    if (data) {
      togglePopup('login');
    }
  };

  const handleSubmit = async (event) => {
    event.preventDefault();

    if (!agreeTerms) {
      alert("You must agree to the terms and conditions.");
      return;
    }

    const isLogin = currState === "Login";
    const endpoint = isLogin
      ? "http://localhost:5000/user/login"
      : "http://localhost:5000/user/signup";

    const data = isLogin ? { email, password } : { name, email, password };

    try {
      const responseData = await handleFormSubmission(endpoint, data, `${currState} successful!`, (errorResult) => {
        console.error(`${currState} Error:`, errorResult.message);
        if (errorResult.message && errorResult.message.includes("Email already in use")) {
          alert("Email already exists! Switching to login...");
          updatePopupState("Login");
        } else if (errorResult.message && errorResult.message.includes("Invalid credentials, incorrect email")) {
          alert("Email not found! Switching to sign up...");
          updatePopupState("Sign Up");
        } else if (errorResult.message && errorResult.message.includes("Invalid credentials, incorrect password")) {
          alert("Incorrect password.");
        } else {
          alert(`Error: ${errorResult.message || "Something went wrong."}`);
        }
      });

      if (responseData) {
        if (isLogin && responseData.userId) {
          setIsLoggedIn(true);
          localStorage.setItem('isLoggedIn', 'true');
          localStorage.setItem('userId', responseData.userId);
          updateAuthUI();
          togglePopup();
          if (onLoginSuccessCallback) {
            onLoginSuccessCallback(responseData.userId);
          }
        } else if (!isLogin) {
          updatePopupState("Login");
        }
      }
    } catch (error) {
      console.error(`${currState} Error:`, error);
      alert("Something went wrong, please try again.");
    }
  };

  const handleBasketClick = (event) => {
    const userId = localStorage.getItem('userId');
    const cartItems = JSON.parse(localStorage.getItem('cartItems')) || {};
    const isCartEmpty = Object.keys(cartItems).length === 0;

    if (!userId) {
      event.preventDefault();
      alert('Please sign in to view your cart.');
      window.scrollTo(0, 0);
      setTimeout(() => {
        const signInButton = document.getElementById('sign-in-btn');
        if (signInButton) {
          signInButton.click();
        }
      }, 200);
      return;
    }

    if (isLoggedIn && isCartEmpty) {
      event.preventDefault();
      alert('Your cart is empty. Please add at least one item to proceed.');
      return;
    }
  };

  const handleLogout = () => {
    setIsLoggedIn(false);
    localStorage.removeItem('isLoggedIn');
    localStorage.removeItem('userId');
    localStorage.removeItem('cartItems');
    window.location.reload();
    updateAuthUI();
    setShowProfileOptions(false);
  };

  useEffect(() => {
    updateAuthUI();
  }, [isLoggedIn]);

  useEffect(() => {
    const handleOutsideClick = (event) => {
      if (document.getElementById('profile-icon') && document.getElementById('profile-options') &&
          !document.getElementById('profile-icon').contains(event.target) &&
          !document.getElementById('profile-options').contains(event.target)) {
        setShowProfileOptions(false);
      }
    };

    document.addEventListener("click", handleOutsideClick);
    return () => {
      document.removeEventListener("click", handleOutsideClick);
    };
  }, []);

  return (
    <div>
      <button id="sign-in-btn" onClick={() => togglePopup('login')}>Sign In</button>
      <img id="profile-icon" src="profile-icon.png" alt="Profile" onClick={() => setShowProfileOptions(!showProfileOptions)} style={{ display: isLoggedIn ? 'inline-block' : 'none' }} />
      <div id="profile-options" style={{ display: showProfileOptions ? 'block' : 'none' }}>
        <button id="bag-option" onClick={() => { setShowProfileOptions(false); /* Implement bag logic */ }}>Bag</button>
        <button id="logout-option" onClick={handleLogout}>Logout</button>
      </div>
      <a id="basket-icon" href="/cart.html" onClick={handleBasketClick}>Basket</a>

      {showLoginPopup && (
        <div id="login-popup" style={{ display: 'grid' }}>
          <button id="close-btn" onClick={() => togglePopup()}>Close</button>
          <h2 id="popup-title">{currState}</h2>
          <form onSubmit={handleSubmit}>
            {currState === "Sign Up" && <input id="name" type="text" placeholder="Name" value={name} onChange={(e) => setName(e.target.value)} required />}
            <input id="email" type="email" placeholder="Email" value={email} onChange={(e) => setEmail(e.target.value)} required />
            <input id="password" type="password" placeholder="Password" value={password} onChange={(e) => setPassword(e.target.value)} required />
            <div>
              <input id="check-box" type="checkbox" checked={agreeTerms} onChange={() => setAgreeTerms(!agreeTerms)} />
              <label htmlFor="check-box">I agree to the terms and conditions</label>
            </div>
            <button id="submit-btn" type="submit">{currState === "Login" ? "Login" : "Create account"}</button>
          </form>
          <div id="switch-action" onClick={(event) => { if (event.target.classList.contains("switch-link")) { toggleState(); } }}>
            {currState === "Login" ? `Create a new account? <span id="switch-to-signup" className="switch-link">Click here</span>` : `Already have an account? <span id="switch-to-login" className="switch-link">Login here</span>`}
          </div>
          <a id="forgot-password-container-link" href="#forgot" onClick={(e) => { e.preventDefault(); togglePopup('forgot'); }} style={{ display: currState === "Login" ? "block" : "none" }}>Forgot Password?</a>
        </div>
      )}

      {showForgotPasswordPopup && (
        <div id="forgot-password-popup" style={{ display: 'grid' }}>
          <button id="close-forgot-password-btn" onClick={() => togglePopup()}>Close</button>
          <h2>Reset Password</h2>
          <form onSubmit={handleForgotPasswordSubmit}>
            <input id="forgot-email" type="email" placeholder="Email" value={forgotEmail} onChange={(e) => setForgotEmail(e.target.value)} required />
            <input id="new-forgot-password" type="password" placeholder="New Password" value={newForgotPassword} onChange={(e) => setNewForgotPassword(e.target.value)} required />
            <button id="reset-password-btn" type="submit">Reset Password</button>
          </form>
          <a id="back-to-login" href="#login" onClick={(e) => { e.preventDefault(); togglePopup('login'); }}>Back to Login</a>
        </div>
      )}
    </div>
  );
}

export default LoginSignup;
